        // ---- reuse and retention
        public const string PreExisting = "Workbench used a USB driver already on this PC. It will leave that driver in place.";
        public const string KeptFormat = "The USB driver was kept because {0}. No other driver was removed.";
        public static string Kept(string because) => string.Format(KeptFormat, because);

        // ---- the one sentence that depends on elevation (an elevated person is never told Windows will ask again)
        public const string AdminRequired = "Administrator permission is required.";
        public static string AdminSentence(ElevationState e) =>
            e == ElevationState.Elevated ? "Workbench already has administrator permission."
            : e == ElevationState.StandardUser ? "Administrator permission is required: Windows will ask for an administrator's name and password."
            : AdminRequired;
        public static string SetupBodyFor(ElevationState e) => SetupBody.Replace(AdminRequired, AdminSentence(e));
        public static string CloseBodyFor(ElevationState e) => CloseBody.Replace(AdminRequired, AdminSentence(e));

        /// <summary>the PC changes Hakchi2 CE 3.9.3's driver setup makes, shown before consent</summary>
        public static readonly string[] PinnedHelperChanges =
        {
            "Adds a Windows driver package, nintendo_classic.inf (Microsoft's WinUSB driver for the console's USB identity, 1F3A:EFE8), to this PC's driver store, and uses it for the console whenever it is connected.",
            "Creates a new certificate named \"USB\\VID_1F3A&PID_EFE8 (libwdi autogenerated)\" and adds it to this PC's Trusted Root Certification Authorities and Trusted Publishers lists, so Windows accepts that driver package. Its private key is deleted right after the package is signed. The certificate stays on this PC after setup.",
            "Copies two Microsoft driver setup files (WdfCoInstaller01011.dll and WinUSBCoInstaller2.dll) into the Windows System32 folder if they are not there already.",
            "Changes the name Windows shows for its WinUSB service to \"WinUSB - Kernel Driver\" followed by a date and version.",
            "Turns off restore-point creation for device setup while it runs, then puts that setting back.",
            "Writes temporary setup files to a folder on this PC and deletes them afterward. Windows keeps its own record of the setup in its logs.",
        };
        /// <summary>the PC changes Workbench's own driver setup makes (CcsDriverPackage.cs, DriverActionHost.cs), shown before consent</summary>
        public static readonly string[] CcsPackageChanges =
        {
            "Adds a Windows driver package named ccs_console_usb.inf to this PC's driver store and uses it for your NES Classic whenever it is connected (USB identity 1F3A:EFE8). The package contains no driver program: it tells Windows to use its own WinUSB driver for the console.",
            "Creates a new certificate named \"CCS Console Workbench USB driver (1F3A-EFE8)\" followed by a number for this setup, and adds it to this PC's Trusted Root Certification Authorities and Trusted Publishers lists so Windows accepts that driver package. The certificate can sign nothing else: its private key exists only in memory during the setup and is never saved. The certificate stays on this PC with the driver.",
            "Writes the package's two files to a new temporary folder that only administrators can change, and deletes that folder afterward. Windows keeps its own record of the setup in its logs.",
            "Nothing else is installed, and no other driver or certificate is replaced or removed.",
        };
        public static List<string> SetupDetails(DriverSetupPlan plan) => (plan?.Changes ?? new List<string>()).ToList();

