        /// <summary>the plain reason a driver or certificate was kept (completes "...was kept because ...")</summary>
        public static string Because(RetainReason r)
        {
            switch (r)
            {
                case RetainReason.RecordIncomplete: return "Workbench's record of the setup is incomplete (Workbench may have closed unexpectedly)";
                case RetainReason.RemovalIncomplete: return "the earlier removal did not finish";
                case RetainReason.SetupNotConfirmed: return "Workbench could not confirm that its setup finished";
                case RetainReason.OwnershipUncertain: return "Workbench cannot show for certain that it added this driver";
                case RetainReason.PreExisting: return "it was already on this PC before Workbench used it";
                case RetainReason.InboxDriver: return "it is part of Windows";
                case RetainReason.OtherToolPackage: return "it belongs to another program";
                case RetainReason.PackageMissing: return "it is no longer on this PC";
                case RetainReason.PackageChanged: return "it has changed since Workbench set it up";
                case RetainReason.SharedWithOtherDevice: return "another USB device on this PC also uses it";
                case RetainReason.RestartPending: return "Windows is waiting for a restart to finish a driver change";
                case RetainReason.ConsoleOperationActive: return "a console operation is still running";
                case RetainReason.ConsoleWriteInProgress: return "the console is being written to";
                case RetainReason.UnresolvedConsoleResult: return "the result of the last console operation is not settled yet";
                case RetainReason.ParentAppNeedsIt: return "Classic Cart Studio is still using the console connection";
                case RetainReason.AnotherWorkbenchOperation: return "another Workbench operation still needs it";
                case RetainReason.OtherProgramMayUseIt: return "another program that uses the console (such as Hakchi) is open";
                case RetainReason.StateUnreadable: return "Workbench could not read this PC's driver list";
                case RetainReason.OtherPc: return "the record was made on another PC";
                case RetainReason.ElevationRefused: return "Windows did not give administrator permission";
                case RetainReason.RemovalFailed: return "Windows could not remove it";
                case RetainReason.ActionUnavailable: return "this Workbench window cannot make driver changes";
                case RetainReason.RefusedAtLastCheck: return "a last check found it is no longer exactly as Workbench set it up, or another device now uses it";
                case RetainReason.CertificatePreExisting: return "it was already on this PC before the setup";
                case RetainReason.CertificateShared: return "another driver package on this PC is signed with it";
                case RetainReason.CertificateChanged: return "it has changed since the setup";
                case RetainReason.CertificateSharingUnknown: return "Workbench could not check every driver package on this PC for it";
                case RetainReason.CertificateWithKeptDriver: return "the driver it signed was kept";
                case RetainReason.PackageStillPresent: return "the driver it signed is still on this PC";
                case RetainReason.RestartNotSeen: return "Windows has not restarted since the driver was removed, so the removal may not be finished";
                case RetainReason.StepInterrupted: return "Workbench's administrator step stopped before it finished";
                default: return "Workbench could not show that removing it is safe";
            }
        }
    }
